export interface DownloadUrlOptions {
  /** `Content-Type` the storage answers the download with. */
  contentType: string;
  expiresInSeconds: number;
}

/**
 * Nest injection token for the `ObjectStorage` that holds avatars, in a
 * bucket anyone can read.
 */
export const AVATAR_STORAGE = Symbol("AVATAR_STORAGE");

/**
 * Where uploaded files live, outside PostgreSQL. Keys are generated by the
 * server. Used as the Nest injection token for the configured implementation.
 */
export abstract class ObjectStorage {
  abstract put(key: string, body: Buffer, contentType: string): Promise<void>;

  /** Succeeds when the object is already gone. */
  abstract delete(key: string): Promise<void>;

  /** A signed URL that reads the object without a session until it expires. */
  abstract getDownloadUrl(
    key: string,
    options: DownloadUrlOptions
  ): Promise<string>;

  /**
   * A permanent URL that reads the object without signing. Only the avatar
   * bucket has one.
   */
  abstract getPublicUrl(key: string): string;
}
